73	 */
74	
75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /**
81	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
82	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
83	     * addresses are lower-cased before being stored.
84	     */
85	    private static final Pattern EMAIL_PATTERN =
86	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
87	
88	    /** An owner's postcode, when supplied, must be exactly four digits. */
89	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
90	
91	    /**
92	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
93	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
94	     */
95	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
96	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
97	
98	    /**
99	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
100	     * named logger keeps them addressable independently of the class's diagnostic logging.
101	     */
102	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
103	
104	    /**
105	     * Dedicated logger for the welcome notification enqueued on a successful create. Emitting it on a
106	     * well-known, separately named logger keeps the notification stream addressable independently of the
107	     * audit records and the class's diagnostic logging.
108	     */
109	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
110	
111	    /**
112	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED}
113	     * audit event. It is process-wide (static) so the ordering holds across every owner created,
114	     * regardless of which controller instance handles the request.
115	     */
116	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong(0);
117	
118	    /** Serializes the immutable structured audit event to its canonical JSON representation. */
119	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
120	
121	    /**
122	     * Schema version stamped onto every structured {@code OWNER_CREATED} audit event. Bumped to 2
123	     * alongside the version-2 owner identity: the event now carries a {@code schemaVersion} field and
124	     * its {@code memberId} is the version-2 member id.
125	     */
126	    private static final int AUDIT_SCHEMA_VERSION = 2;
127	
128	    /**
129	     * Maximum number of owners a single city may contain. A create that would take the owner's city
130	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
131	     */
132	    private static final int CITY_OWNER_LIMIT = 50;
133	
134	    /**
135	     * Number of owners a city must already hold for a create response and owner read to flag that the
136	     * city is approaching capacity. When the city holds between this many and {@link #CITY_OWNER_LIMIT}
137	     * minus one owners (40-49), the owner's {@code capacityWarning} is {@code true}; the hard rejection
138	     * at {@link #CITY_OWNER_LIMIT} is unchanged.
139	     */
140	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
141	
142	    /**
143	     * Maximum number of owners that may be registered on a single day. A create that would take the
144	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
145	     * have already been created that day - is rejected with a 429.
146	     */
147	    private static final int DAILY_OWNER_LIMIT = 100;
148	
149	    /**
150	     * Number of owners that must already have been created for a given day before the create
151	     * response flags a bulk sign-up. When more than this many owners already share a
152	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
153	     */
154	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
155	
156	    /**
157	     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
158	     * like a weekend and rolled forward to the next non-holiday business day.
159	     */
160	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
161	        LocalDate.of(2026, 1, 1),
162	        LocalDate.of(2026, 1, 26),
163	        LocalDate.of(2026, 4, 25),
164	        LocalDate.of(2026, 12, 25),
165	        LocalDate.of(2026, 12, 28));
166	
167	    /**
168	     * Request header carrying the client-supplied idempotency key. When a create repeats with a key
169	     * already seen, the originally created owner is returned instead of creating a duplicate.
170	     */
171	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
172	
173	    private final ClinicService clinicService;
174	
175	    private final OwnerMapper ownerMapper;
176	
177	    private final PetMapper petMapper;
178	
179	    private final VisitMapper visitMapper;
180	
181	    private final HttpServletRequest request;
182	
183	    /**
184	     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
185	     * create with an already-seen key returns the originally created owner rather than a duplicate.
186	     */
187	    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();
188	
189	    public OwnerRestControllerV1(ClinicService clinicService,
190	                                 OwnerMapper ownerMapper,
191	                                 PetMapper petMapper,
192	                                 VisitMapper visitMapper,
193	                                 HttpServletRequest request) {
194	        this.clinicService = clinicService;
195	        this.ownerMapper = ownerMapper;
196	        this.petMapper = petMapper;
197	        this.visitMapper = visitMapper;
198	        this.request = request;
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
204	        Collection<Owner> owners;
205	        if (lastName != null) {
206	            owners = this.clinicService.findOwnerByLastName(lastName);
207	        } else {
208	            owners = this.clinicService.findAllOwners();
209	        }
210	        if (owners.isEmpty()) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
224	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
225	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
226	        ownerDto.setRiskFlag(computeRiskFlag(owner));
227	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
228	    }
229	
230	    /**
231	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
232	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
233	     * owner sign-ups.
234	     *
235	     * @param registrationDate the day to inspect, or {@code null}
236	     * @return {@code true} when more than the threshold of owners are registered on that day
237	     */
238	    private boolean isBulkSignupDay(LocalDate registrationDate) {
239	        return registrationDate != null
240	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
241	    }
242	
243	    /**
244	     * Determines whether the supplied city is approaching its per-city capacity, i.e. it currently
245	     * holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_LIMIT} minus one
246	     * owners (40-49). This flags a city nearing the hard limit of {@link #CITY_OWNER_LIMIT}; that hard
247	     * rejection is unchanged.
248	     *
249	     * @param city the city to inspect, or {@code null}
250	     * @return {@code true} when the city holds 40-49 owners
251	     */
252	    private boolean isApproachingCityCapacity(String city) {
253	        if (city == null) {
254	            return false;
255	        }
256	        long count = countOwnersInCity(city);
257	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
258	    }
259	
260	    /**
261	     * Determines whether the supplied city is over its soft capacity, i.e. it currently holds at
262	     * least {@link #CITY_CAPACITY_WARNING_THRESHOLD} owners - the soft limit that sits below the hard
263	     * per-city limit of {@link #CITY_OWNER_LIMIT}. Unlike {@link #isApproachingCityCapacity}, which is
264	     * a window that closes once the city is full, this stays {@code true} all the way up to and
265	     * including the hard limit, so a city at capacity is still reported as over its soft capacity.
266	     *
267	     * @param city the city to inspect, or {@code null}
268	     * @return {@code true} when the city holds at least {@link #CITY_CAPACITY_WARNING_THRESHOLD} owners
269	     */
270	    private boolean isOverSoftCityCapacity(String city) {
271	        return city != null && countOwnersInCity(city) >= CITY_CAPACITY_WARNING_THRESHOLD;
272	    }
273	
274	    /**
275	     * Determines whether an owner's email address is disposable-adjacent, i.e. its domain (the part
276	     * after the '@', compared case-insensitively) is a subdomain of one of the {@link
277	     * #DISPOSABLE_EMAIL_DOMAINS} that are blocked outright at create time. An exact disposable domain
278	     * is rejected with a 400 when the owner is created, so it never survives on a stored owner; a
279	     * subdomain such as {@code mail.mailinator.com} is admitted but is close enough to a disposable
280	     * provider to be flagged for review.
281	     *
282	     * @param email the owner's normalized email address, or {@code null}/blank when none is on file
283	     * @return {@code true} when the email's domain is a subdomain of a known disposable domain
284	     */
285	    private boolean isDisposableAdjacentEmail(String email) {
286	        if (!StringUtils.hasText(email)) {
287	            return false;
288	        }
289	        int at = email.indexOf('@');
290	        if (at < 0) {
291	            return false;
292	        }
293	        String domain = email.substring(at + 1).toLowerCase();
294	        return DISPOSABLE_EMAIL_DOMAINS.stream().anyMatch(blocked -> domain.endsWith("." + blocked));
295	    }
296	
297	    /**
298	     * Computes the owner's {@code riskFlag}, the review signal derived on read. It is {@code true}
299	     * when any of these hold: the owner is a possible duplicate (see
300	     * {@link #findPossibleDuplicate(Owner)}), the owner's email domain is disposable-adjacent (see
301	     * {@link #isDisposableAdjacentEmail(String)}), or the owner's city is over its soft capacity (see
302	     * {@link #isOverSoftCityCapacity(String)}); otherwise {@code false}.
303	     *
304	     * @param owner the owner to inspect
305	     * @return {@code true} when any review signal trips, otherwise {@code false}
306	     */
307	    private boolean computeRiskFlag(Owner owner) {
308	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
309	            || isDisposableAdjacentEmail(owner.getEmail())
310	            || isOverSoftCityCapacity(owner.getCity());
311	    }
