343	    /**
344	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
345	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
346	     * submitted address is canonicalized, the required fields and the optional postcode and
347	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
348	     * registration date is defaulted to the server date when absent and rolled forward to a business
349	     * day. The household id and identity key are derived; a create whose identity key matches an
350	     * existing, non-deleted owner is rejected with a 409 unless it opts in with {@code sharesHousehold},
351	     * and otherwise a soft-match duplicate is flagged.
352	     *
353	     * @param ownerFieldsDto the submitted owner fields
354	     * @return the normalized owner, not yet persisted
355	     */
356	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
357	        resolveAddressFields(ownerFieldsDto);
358	        validateRequiredFields(ownerFieldsDto);
359	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
360	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
361	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
362	        owner.setEmail(normalizeEmail(owner.getEmail()));
363	        validateRegistrationDate(owner.getRegistrationDate());
364	        if (owner.getRegistrationDate() == null) {
365	            owner.setRegistrationDate(LocalDate.now());
366	        }
367	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
368	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
369	        resolveHouseholdIdentity(owner, sharesHousehold);
370	        return owner;
371	    }
