373	    /**
374	     * Places the owner about to be created into its household and settles its identity against the
375	     * owners already on file. The owner's {@code householdId} is still derived deterministically from
376	     * its last name and postcode (it drives the household size and membership-level cap), but identity
377	     * is now decided solely by the {@code identityKey}, the SHA-256 digest over the normalized
378	     * telephone, email and the last name's Soundex code. Unless the request opted into a shared
379	     * household, an owner whose identity key matches any existing, non-deleted owner is rejected with a
380	     * 409; and, again only when the household was not opted into, a soft-match against an existing owner
381	     * flags the new owner as a possible duplicate. Two owners sharing a last name and postcode but with
382	     * different telephones now derive different identity keys, so they are admitted (as a soft match)
383	     * rather than rejected, with their membership level later capped by
384	     * {@link #applyMembershipLevelCap(Owner)}.
385	     *
386	     * @param owner the normalized owner about to be created, with its contact details already normalized
387	     * @param sharesHousehold whether the request opted into joining an existing household
388	     */
389	    private void resolveHouseholdIdentity(Owner owner, boolean sharesHousehold) {
390	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
391	        owner.setIdentityKey(buildIdentityKey(owner));
392	        if (!sharesHousehold) {
393	            rejectDuplicateIdentity(owner);
394	        }
395	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
396	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
397	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
398	    }
