400	    /**
401	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
402	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
403	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
404	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
405	     * registration date, measured before it is saved, which the caller uses to decide the response's
406	     * {@code bulkSignupWarning}.
407	     *
408	     * @param owner the normalized owner about to be created
409	     * @return the number of owners already registered on the owner's registration date
410	     */
411	    private long enforceCreateLimits(Owner owner) {
412	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
413	            throw new OwnerCityFullException(owner.getCity());
414	        }
415	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
416	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
417	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
418	        }
419	        return ownersRegisteredOnDay;
420	    }
