424	     * de-duplicated member id, the number of existing namesakes, the household size once the
425	     * new owner is added, and the membership-level ceiling imposed by the household the owner joins.
426	     *
427	     * @param owner the normalized owner about to be created
428	     */
429	    private void finalizeOwnerForCreate(Owner owner) {
430	        owner.setMemberId(buildMemberId(owner));
431	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
432	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
