448	        activeHouseholdMembers(owner.getHouseholdId()).stream()
449	            .mapToInt(org.springframework.samples.petclinic.mapper.MembershipLevel::forOwner)
450	            .max()
451	            .ifPresent(maxLevel -> owner.setMembershipLevelCap(maxLevel + 1));
452	    }
