548	    /**
549	     * Canonicalizes the submitted address fields into the form that is validated, stored and
550	     * returned, before any required-field check or mapping runs. This is the single place a create
551	     * request's address input is resolved.
552	     *
553	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
554	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
555	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
556	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
557	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
558	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
559	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
560	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
561	     * that is blank only after normalization is left blank here and rejected later by
562	     * {@link #validateRequiredFields}.
563	     *
564	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
565	     */
566	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
567	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
568	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
569	        if (!line1.isEmpty()) {
570	            ownerFieldsDto.setAddressLine1(line1);
571	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
572	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
573	        }
574	        else {
575	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
576	        }
577	    }
