579	    /**
580	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
581	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
582	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
583	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
584	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
585	     * normalization is still rejected.
586	     *
587	     * @param ownerFieldsDto the submitted owner fields
588	     */
589	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
590	        List<String> missingFields = new ArrayList<>();
591	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
592	            missingFields.add("firstName");
593	        }
594	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
595	            missingFields.add("lastName");
596	        }
597	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
598	            missingFields.add("address");
599	        }
600	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
601	            missingFields.add("city");
602	        }
603	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
604	            missingFields.add("telephone");
605	        }
606	        if (!missingFields.isEmpty()) {
607	            throw new MissingOwnerFieldsException(missingFields);
608	        }
609	    }
