611	    /**
612	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
613	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
614	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
615	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
616	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
617	     * whose {@code errors} array lists {@code postcode}.
618	     *
619	     * @param postcode the submitted postcode, or {@code null} when none was supplied
620	     * @param city the owner's city, whose region determines the acceptable postcode range
621	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
622	     */
623	    private void validatePostcode(String postcode, String city) {
624	        if (!StringUtils.hasText(postcode)) {
625	            return;
626	        }
627	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
628	            throw new InvalidOwnerFieldsException(List.of("postcode"));
629	        }
630	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
631	            throw new InvalidOwnerFieldsException(List.of("postcode"));
632	        }
633	    }
