650	    /**
651	     * Rejects a submitted owner whose derived {@code identityKey} matches that of any existing,
652	     * non-deleted owner - the same normalized telephone, email and last-name Soundex, which marks the
653	     * same person being entered twice. This single identity key is the whole of duplicate detection:
654	     * because the telephone is part of the key, distinct people who merely share a last name and
655	     * postcode (but differ in telephone) derive a different key and so are admitted rather than
656	     * rejected. Soft-deleted owners are ignored, and the email-domain blocklist has already been
657	     * applied when the email was normalized. A genuine identity collision is reported to the client as
658	     * a 409 Conflict. A request may knowingly bypass this check by opting in with
659	     * {@code sharesHousehold}, in which case it is not performed.
660	     *
661	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
662	     */
663	    private void rejectDuplicateIdentity(Owner owner) {
664	        boolean identityInUse = this.clinicService.findAllOwners().stream()
665	            .filter(existing -> !existing.isDeleted())
666	            .anyMatch(existing -> owner.getIdentityKey().equals(existing.getIdentityKey()));
667	        if (identityInUse) {
668	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
669	        }
670	    }
