672	    /**
673	     * Returns the owners that currently belong to the household identified by {@code householdId} -
674	     * those sharing that derived id that have not been soft-deleted. Soft-deleted owners are excluded
675	     * because they no longer count as present members, so this is the household as it stands for the
676	     * owner being created. This is the single lookup of a household's current members behind the
677	     * household checks that reason about who is already there.
678	     *
679	     * @param householdId the derived household identifier to look up
680	     * @return the existing, non-deleted owners sharing that household, in no particular order
681	     */
682	    private List<Owner> activeHouseholdMembers(String householdId) {
683	        return this.clinicService.findAllOwners().stream()
684	            .filter(existing -> !existing.isDeleted())
685	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
686	            .collect(Collectors.toList());
687	    }
