689	    /**
690	     * Derives the owner's version-2 {@code identityKey} as the SHA-256 hex digest over
691	     * {@code 'V2' + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the
692	     * leading {@link OwnerIdentityVersion#TAG version tag} is mixed in so no key produced under version
693	     * 1 recurs. The telephone and email have already been normalized (the email lower-cased, or the
694	     * empty string when none was supplied) and the last name is reduced to its {@link Soundex} code.
695	     * Because the normalized
696	     * telephone is part of the key, two owners who differ only in telephone derive different identity
697	     * keys, so they are not the same identity even when they share a household.
698	     *
699	     * @param owner the normalized owner about to be created, with its contact details already normalized
700	     * @return the derived identity key, as 64 lower-case hex characters
701	     */
702	    private String buildIdentityKey(Owner owner) {
703	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
704	        return Sha256.hex(OwnerIdentityVersion.TAG + "|" + owner.getTelephone() + "|" + email + "|"
705	            + Soundex.encode(owner.getLastName()));
706	    }
707	
708	    /**
709	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner whose
710	     * derived {@code identityKey} differs from an existing owner's - so it is not the same identity, and
711	     * not a 409 - yet shares that owner's last-name {@link Soundex} code and {@code postcode}. Such an
712	     * owner is still created, but is flagged as a possible duplicate of the matching owner. In
713	     * particular, two owners with the same last name and postcode but different telephones now derive
714	     * different identity keys, so instead of the old hard household-duplicate rejection they surface
715	     * here as a soft match. This is only consulted for owners that did not opt into a shared household:
716	     * an owner that declares {@code sharesHousehold} is a known household member, not a suspected
717	     * duplicate, so it is never flagged. The comparison only applies when a postcode was supplied, since
718	     * both owners must share one; when several existing owners match, the earliest (lowest id) is used.
719	     *
720	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
721	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
722	     */
723	    private Integer findPossibleDuplicate(Owner owner) {
724	        if (!StringUtils.hasText(owner.getPostcode())) {
725	            return null;
726	        }
727	        String soundex = Soundex.encode(owner.getLastName());
728	        return this.clinicService.findAllOwners().stream()
729	            .filter(existing -> !existing.isDeleted())
730	            .filter(existing -> !owner.getIdentityKey().equals(existing.getIdentityKey()))
731	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
732	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
733	            .map(Owner::getId)
734	            .filter(id -> id != null)
735	            .min(Integer::compareTo)
736	            .orElse(null);
737	    }
