739	    /**
740	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
741	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
742	     * address; the accepted value is lower-cased before it is stored and returned.
743	     *
744	     * @param email the raw email value submitted by the client, or {@code null}
745	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
746	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
747	     */
748	    private String normalizeEmail(String email) {
749	        if (!StringUtils.hasText(email)) {
750	            return email;
751	        }
752	        if (!EMAIL_PATTERN.matcher(email).matches()) {
753	            throw new InvalidOwnerFieldsException(List.of("email"));
754	        }
755	        String normalized = email.toLowerCase();
756	        String domain = normalized.substring(normalized.indexOf('@') + 1);
757	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
758	            throw new InvalidOwnerFieldsException(List.of("email"));
759	        }
760	        return normalized;
761	    }
