763	    /**
764	     * Assigns the owner's member id, formatted {@code <REGION><FY><HASH8><CHK>}. The region is derived
765	     * from the owner's postcode (falling back to its city), FY is the two-digit fiscal year of the
766	     * (business-day-adjusted) registration date, and the id itself - region, fiscal year, the hash of
767	     * the owner's normalized telephone and last name, and the trailing Luhn check digit - is composed
768	     * by {@link MemberId}. When the composed id collides with an existing owner's member id, it is
769	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of two or more that makes it
770	     * unique.
771	     *
772	     * @param owner the normalized owner about to be created
773	     * @return the assigned, de-duplicated member id
774	     */
775	    private String buildMemberId(Owner owner) {
776	        String region = OwnerIdentityVersion.regionCode(
777	            OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity()));
778	        int fiscalYear = FiscalYear.twoDigit(owner.getRegistrationDate());
779	        String id = MemberId.forRegionYearAndIdentity(region, fiscalYear, owner.getTelephone(), owner.getLastName());
780	        return deduplicateMemberId(id);
781	    }
782	
783	    /**
784	     * De-duplicates a freshly composed member id against the ids of all existing owners. When the id is
785	     * already unique it is returned unchanged; otherwise {@code -<n>} is appended, using the smallest
786	     * {@code n} of two or more that yields an id no existing owner holds.
787	     *
788	     * @param id the composed member id, before de-duplication
789	     * @return the same id when unique, otherwise the id with the smallest available {@code -<n>} suffix
790	     */
791	    private String deduplicateMemberId(String id) {
792	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
793	            .map(Owner::getMemberId)
794	            .filter(existing -> existing != null)
795	            .collect(Collectors.toSet());
796	        if (!existingIds.contains(id)) {
797	            return id;
798	        }
799	        int suffix = 2;
800	        while (existingIds.contains(id + "-" + suffix)) {
801	            suffix++;
802	        }
803	        return id + "-" + suffix;
804	    }
