856	    /**
857	     * Rolls a registration date forward to a business day. A registration date must fall on a
858	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
859	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
860	     * returned unchanged. Every value derived from the registration date (such as the member id's
861	     * fiscal-year segment) and the daily create-limit therefore use the adjusted date.
862	     *
863	     * @param date the effective registration date, whether supplied or defaulted to the server date
864	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
865	     */
866	    private LocalDate toBusinessDay(LocalDate date) {
867	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
868	            date = date.plusDays(1);
869	        }
870	        return date;
871	    }
