2	
3	import org.springframework.beans.factory.annotation.Autowired;
4	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
5	import org.springframework.context.annotation.Bean;
6	import org.springframework.context.annotation.Configuration;
7	import org.springframework.security.config.Customizer;
8	import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
9	import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
10	import org.springframework.security.config.annotation.web.builders.HttpSecurity;
11	import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
12	import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
13	import org.springframework.security.crypto.password.PasswordEncoder;
14	import org.springframework.security.web.SecurityFilterChain;
15	
16	import javax.sql.DataSource;
17	
18	@Configuration
19	@EnableMethodSecurity(prePostEnabled = true) // Enable @PreAuthorize method-level security
20	@ConditionalOnProperty(name = "petclinic.security.enable", havingValue = "true")
21	public class BasicAuthenticationConfig {
22	
23	    @Autowired
24	    private DataSource dataSource;
25	
26	    @Bean
27	    public PasswordEncoder passwordEncoder() {
28	        return new BCryptPasswordEncoder();
29	    }
30	
31	
32	
33	    @Bean
34	    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
35	        // @formatter:off
36	        http
37	            .csrf(AbstractHttpConfigurer::disable)
38	            .authorizeHttpRequests((authz) -> authz
39	                .anyRequest().authenticated())
40	                .httpBasic(Customizer.withDefaults());
41	        // @formatter:on
42	        return http.build();
43	    }
44	
45	    @Autowired
46	    public void configureGlobal(AuthenticationManagerBuilder auth) throws Exception {
47	        // @formatter:off
48	        auth
49	            .jdbcAuthentication()
50	                .dataSource(dataSource)
51	                .usersByUsernameQuery("select username,password,enabled from users where username=?")
52	                .authoritiesByUsernameQuery("select username,role from roles where username=?");
53	        // @formatter:on
54	    }
55	}
