3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region), preferring the postcode: the region is
7	 * looked up by postcode range first, and only when the postcode is absent or in
8	 * no known range does it fall back to a fixed city-to-region table. This returns
9	 * the same region for the known cities but disambiguates cities that share a name.
10	 *
11	 * <p>Kept as a plain static helper - rather than a method on {@link OwnerMapper} -
12	 * so MapStruct does not mistake it for an implicit String-to-String property
13	 * mapping and apply it to unrelated fields.
14	 *
15	 * <p>Public, like its sibling {@link MembershipLevel}, so the single region table
16	 * can be reused wherever an owner's region is needed rather than being
17	 * duplicated - callers outside this package derive the region through
18	 * {@link #forPostcodeAndCity(String, String)} (or {@link #forCity(String)} when
19	 * only the city is available) instead of holding their own copy of the tables.
20	 */
21	public final class OwnerLocality {
22	
23	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
24	    private static final Map<String, String> CITY_REGION = Map.of(
25	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
26	
27	    /** Region -> inclusive 4-digit postcode range {low, high}. */
28	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
29	        "NSW", new int[] {2000, 2099},
30	        "VIC", new int[] {3000, 3099},
31	        "QLD", new int[] {4000, 4099});
32	
33	    /** Region -> IANA timezone; anything not listed derives no timezone (null). */
34	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
35	        "NSW", "Australia/Sydney",
36	        "VIC", "Australia/Melbourne",
37	        "QLD", "Australia/Brisbane");
38	
39	    private OwnerLocality() {
40	    }
41	
42	    /**
43	     * Returns the canonical region for the given owner, preferring the postcode:
44	     * the region is derived from the postcode range first, falling back to the
45	     * city-to-region table only when the postcode is absent or in no known range.
46	     *
47	     * @param postcode the owner's postcode, or {@code null} when none was supplied
48	     * @param city the owner's city
49	     * @return the derived locality (region)
50	     */
51	    public static String forPostcodeAndCity(String postcode, String city) {
52	        String region = forPostcode(postcode);
53	        return region != null ? region : forCity(city);
54	    }
55	
56	    /**
57	     * Returns the canonical region for the given city, or "UNKNOWN" when the city
58	     * is not in the fixed table (or is {@code null}).
59	     *
60	     * @param city the owner's city
61	     * @return the derived locality (region)
62	     */
63	    public static String forCity(String city) {
64	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
65	    }
66	
67	    /**
68	     * Returns the IANA timezone for the given region via the fixed region-to-timezone
69	     * table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD ->
70	     * Australia/Brisbane), or {@code null} when the region has no known timezone.
71	     *
72	     * @param region the owner's locality (region)
73	     * @return the IANA timezone name, or {@code null} when none is known
74	     */
75	    public static String timezoneForRegion(String region) {
76	        return region == null ? null : REGION_TIMEZONE.get(region);
77	    }
78	
79	    /**
80	     * Returns whether the given postcode falls within the postcode range of the
81	     * region derived from the city. A city whose region has no fixed range (locality
82	     * "UNKNOWN") accepts any postcode. A postcode that is absent or non-numeric is
83	     * treated as not matching a ranged region.
84	     *
85	     * <p>Callers validate a supplied postcode's four-digit shape separately; this
86	     * method only answers whether the value sits in the city's region range, so the
87	     * single region table is not duplicated at the call site.
88	     *
89	     * @param postcode the owner's postcode, or {@code null} when none was supplied
90	     * @param city the owner's city, whose region determines the acceptable range
91	     * @return {@code true} when the city's region has no fixed range, or the postcode
92	     *         lies within it
93	     */
94	    public static boolean postcodeMatchesCity(String postcode, String city) {
95	        int[] range = REGION_POSTCODES.get(forCity(city));
96	        if (range == null) {
97	            return true;
98	        }
99	        if (postcode == null) {
100	            return false;
101	        }
102	        int value;
103	        try {
104	            value = Integer.parseInt(postcode.trim());
105	        }
106	        catch (NumberFormatException e) {
107	            return false;
108	        }
109	        return value >= range[0] && value <= range[1];
110	    }
111	
112	    /**
113	     * Returns the region whose postcode range contains the given postcode, or
114	     * {@code null} when the postcode is missing, non-numeric or in no known range.
115	     */
116	    private static String forPostcode(String postcode) {
117	        if (postcode == null) {
118	            return null;
119	        }
120	        int value;
121	        try {
122	            value = Integer.parseInt(postcode.trim());
123	        }
124	        catch (NumberFormatException e) {
125	            return null;
126	        }
127	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
128	            int[] range = entry.getValue();
129	            if (value >= range[0] && value <= range[1]) {
130	                return entry.getKey();
131	            }
132	        }
133	        return null;
134	    }
135	
136	}
